n=28
sep={4,9,14,19,24}
g=[[8 if r in sep or c in sep else 0 for c in range(n)] for r in range(n)]
blocks=[list(range(a,min(a+4,n))) for a in [0,5,10,15,20,25]]
# Activated tile rows (2) and columns (3), with overlap encoded as 6.
for tr, rows in enumerate(blocks):
  for tc, cols in enumerate(blocks):
    color = 6 if tr in {1,3} and tc==2 else (2 if tr in {1,3} else (3 if tc==2 else 0))
    for r in rows:
      for c in cols:
        g[r][c]=color
assert len(g)==28 and all(len(row)==28 for row in g)
print(__import__('json').dumps({'action':'submit','grid':g},separators=(',',':')))

n=28
bounds=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]
seps={4,9,14,19,24}
g=[[8 if r in seps or c in seps else 0 for c in range(n)] for r in range(n)]
# Draw inclusive straight-line connections between matching-color marker tiles.
marks={2:[(1,0),(1,4),(3,0)],3:[(0,2),(4,2)]}
for color,pts in marks.items():
  for i,(r1,c1) in enumerate(pts):
    for r2,c2 in pts[i+1:]:
      if r1==r2:
        coords=[(r1,c) for c in range(min(c1,c2),max(c1,c2)+1)]
      elif c1==c2:
        coords=[(r,c1) for r in range(min(r1,r2),max(r1,r2)+1)]
      else: continue
      for tr,tc in coords:
        ra,rb=bounds[tr]; ca,cb=bounds[tc]
        for r in range(ra,rb):
          for c in range(ca,cb):
            old=g[r][c]
            g[r][c]=6 if old not in (0,8,color) else color
# verify boundaries and dimensions
assert len(g)==28 and all(len(row)==28 for row in g)
print(__import__('json').dumps({'action':'submit','grid':g},separators=(',',':')))

